INSERT INTO evaluations (id, ova_id, type, config) VALUES
  ('c0a7e17d-0000-4000-8310-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a01', 'autoevaluacion', '{"questions":[{"id":"e1","correct_answer":"b","feedback_incorrect":"La línea base del alcance son el enunciado, la EDT y su diccionario aprobados."},{"id":"e2","correct_answer":"b","feedback_incorrect":"La regla del 100 % pide que la EDT cubra todo el trabajo y nada más."},{"id":"e3","correct_answer":"c","feedback_incorrect":"La EDT se orienta a entregables: usa sustantivos, no verbos ni fechas."},{"id":"e4","correct_answer":"a","feedback_incorrect":"Agregar funciones que nadie pidió es enchapado en oro."},{"id":"e5","correct_answer":"c","feedback_incorrect":"La decisión formal sobre un cambio corresponde al Comité de Control de Cambios."}]}'::jsonb),
  ('c0a7e17d-0000-4000-8320-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a02', 'autoevaluacion', '{"questions":[{"id":"e1","correct_answer":"b","feedback_incorrect":"La ruta crítica es la secuencia más larga de actividades dependientes y fija la duración mínima."},{"id":"e2","correct_answer":"b","feedback_incorrect":"La holgura total es el inicio tardío menos el inicio temprano: 9 − 6 = 3 semanas."},{"id":"e3","correct_answer":"c","feedback_incorrect":"El retraso consume la holgura y solo el exceso (3 − 2 = 1 semana) llega al final del proyecto."},{"id":"e4","correct_answer":"c","feedback_incorrect":"Agregar recursos a una actividad crítica para acortarla es intensificación."},{"id":"e5","correct_answer":"a","feedback_incorrect":"La ejecución rápida solapa actividades en secuencia y su principal riesgo es el retrabajo."}]}'::jsonb),
  ('c0a7e17d-0000-4000-8330-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a03', 'autoevaluacion', '{"questions":[{"id":"e1","correct_answer":"b","feedback_incorrect":"CPI = EV / AC = 100 / 125 = 0,80: cada peso gastado rinde 80 centavos de trabajo."},{"id":"e2","correct_answer":"b","feedback_incorrect":"El SPI compara EV con PV: un valor de 1,10 indica que se avanza 10 % más rápido de lo planeado."},{"id":"e3","correct_answer":"d","feedback_incorrect":"EAC = BAC / CPI = 480 / 0,80 = $600 millones."},{"id":"e4","correct_answer":"b","feedback_incorrect":"El valor ganado (EV) es el trabajo terminado expresado en dinero del presupuesto."},{"id":"e5","correct_answer":"b","feedback_incorrect":"CV negativa es sobrecosto y SV positiva es adelanto: se está comprando velocidad con más gasto."}]}'::jsonb),
  ('c0a7e17d-0000-4000-8340-000000000001', '6f1c2a3e-1b7d-4c55-9a0e-2d4b8e7f1a04', 'autoevaluacion', '{"questions":[{"id":"e1","correct_answer":"c","feedback_incorrect":"Probabilidad × impacto = 2 × 3 = 6, que está en la zona de prioridad alta (6 a 9)."},{"id":"e2","correct_answer":"b","feedback_incorrect":"Trasladar el impacto a un tercero mediante un contrato o seguro es transferir."},{"id":"e3","correct_answer":"a","feedback_incorrect":"Cambiar el plan para eliminar la amenaza es evitar."},{"id":"e4","correct_answer":"c","feedback_incorrect":"Compartir, explotar y mejorar son estrategias para oportunidades."},{"id":"e5","correct_answer":"b","feedback_incorrect":"Cuando un riesgo ocurre deja de ser incierto: se convierte en un problema."}]}'::jsonb)
